-- 31 The Storyteller: turns the pages and flickers the candle. The markup,
-- the typewriter and its pauses are the engine's (`"rich": true` and
-- `reveal_speed` on the text); this only sets the next page's text, which
-- starts the typewriter over. Generated by tools/gen_scenes.py with the
-- scene, so the pages here and in the scene are one list.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/31-the-storyteller.scene"

local PAGES = {
    "Once, in the [color=#3a78c8]Blue Hollow[/color], there lived a fox called [b]Ember[/b].[pause=0.6] She kept a [icon=sprites/story/key.png] key that opened nothing at all.",
    "One night the wind [wave]sang through the reeds[/wave],[pause=0.5] and the key grew [color=#b8862a]warm[/color] in her paw.",
    "[shake]CRACK![/shake][pause=0.8] The old oak split in two, and behind its bark was a door no bigger than a [icon=sprites/story/heart.png].",
    "Inside lay the [rainbow]hoard of the last dragon[/rainbow] -[pause=0.7] and it was only lanterns, every one of them still lit.",
    "[color=#6a2c5a]The end.[/color][pause=0.9] Press Space to read it again."
}

local post_on = nav.post_all_on(SCENE)
local captions = true
local page = 1
local story, page_no, light, flame, glow, status
local t = 0.0

local function show(i)
    page = i
    if story then Text.set(story, PAGES[page]) end
    if page_no then Text.set(page_no, "- " .. page .. " -") end
end

function init(entity)
    story = Entity.find_by_name("Story")
    page_no = Entity.find_by_name("PageNo")
    light = Entity.find_by_name("CandleLight")
    flame = Entity.find_by_name("Flame")
    glow = Entity.find_by_name("Glow")
    status = Entity.find_by_name("Status")
    if status then Text.set(status, nav.post_status(post_on)) end
end

function update(entity, dt)
    nav.tick(SCENE)
    if nav.post_keys(post_on) and status then Text.set(status, nav.post_status(post_on)) end
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_captions(captions) end
    if Input.is_key_just_pressed("Space") or Input.is_mouse_left_just_pressed() then
        show(page % #PAGES + 1)
    end
    -- The candle breathes: two slow waves and a quick one, never steady.
    t = t + dt
    local f = 1.0 + 0.07 * math.sin(t * 2.3) + 0.05 * math.sin(t * 5.1 + 1.3) + 0.03 * math.sin(t * 13.0)
    if light then Lighting.set_intensity(light, 1.25 * f) end
    if flame then Transform.set_scale(flame, 1.0 + (f - 1.0) * 0.8, f) end
    if glow then Transform.set_scale(glow, f, f) end
end
